fn fixture() -> Value {
    serde_json::from_str(FIXTURE).unwrap()
}

/// Exact input float: Ruby's `Float#to_s` round-trips, and Rust's parser is exact.
fn exact(v: &Value) -> f64 {
    v["ruby"].as_str().unwrap().parse().unwrap()
}

fn build(spec: &Value) -> Elem {
    let tag = spec["tag"].as_str().unwrap();
    let mut e = Elem::new(tag);
    for pair in spec["attrs"].as_array().unwrap() {
        let (k, v) = (pair[0].as_str().unwrap(), &pair[1]);
        e = match v {
            Value::String(s) => e.attr(k, s.clone()),
            n => e.num(k, n.as_f64().unwrap()),
        };
    }
    if let Some(t) = spec.get("text").and_then(Value::as_str) {
        e = e.content(t);
    }
    if let Some(n) = spec.get("line_shift").and_then(Value::as_i64) {
        e = e.attr("line-shift", n.to_string());
    }
    for c in spec.get("children").and_then(Value::as_array).into_iter().flatten() {
        e.push(build(c));
    }
    e
}

#[test]
fn svg_number_formatters_match_ruby() {
    let fx = fixture();
    let rows = fx["numbers"].as_array().unwrap();
    assert!(rows.len() > 250);
    for r in rows {
        let x = exact(r);
        assert_eq!(fmt_num(x), r["js"].as_str().unwrap(), "js_number {}", r["ruby"]);
        assert_eq!(ruby_float(x), r["ruby"].as_str().unwrap(), "Float#to_s");
        let want: f64 = r["round4"].as_f64().unwrap();
        assert_eq!(round4(x), want, "round(4) of {}", r["ruby"]);
        assert_eq!(write_num(x), r["write"].as_str().unwrap(), "Numbers.write {}", r["ruby"]);
    }
}

#[test]
fn svg_read_num_matches_ruby() {
    for r in fixture()["reads"].as_array().unwrap() {
        let got = read_num(r["in"].as_str().unwrap());
        assert_eq!(got, r["out"].as_f64(), "read {:?}", r["in"]);
    }
}

#[test]
fn svg_escaping_matches_ruby() {
    for r in fixture()["escapes"].as_array().unwrap() {
        let s = r["in"].as_str().unwrap();
        assert_eq!(escape_text(s), r["text"].as_str().unwrap());
        assert_eq!(escape_attr(s), r["attr"].as_str().unwrap());
    }
}

#[test]
fn svg_elements_serialize_like_ruby() {
    for r in fixture()["structures"].as_array().unwrap() {
        assert_eq!(build(&r["spec"]).to_xml(), r["xml"].as_str().unwrap(), "spec {}", r["spec"]);
    }
}

#[test]
fn svg_documents_serialize_like_ruby() {
    for d in fixture()["documents"].as_array().unwrap() {
        let mut doc = Document::new(d["width"].as_f64().unwrap(), d["height"].as_f64().unwrap());
        doc.view_box = d["view_box"].as_str().map(str::to_string);
        doc.overflow = d["overflow"].as_str().map(str::to_string);
        for c in d["children"].as_array().unwrap() {
            doc.add(build(c));
        }
        assert_eq!(serialize(&doc), d["xml"].as_str().unwrap());
    }
}

#[test]
fn svg_themes_match_ruby() {
    for t in fixture()["themes"].as_array().unwrap() {
        let th = Theme::get(t["name"].as_str().unwrap()).expect("theme");
        assert_eq!(th.color("background"), t["background"].as_str());
        assert_eq!(th.number("typography", "font_size_normal"), t["font_size_normal"].as_f64());
        assert_eq!(th.palette("flow_palette", 3), t["flow3"].as_str());
        assert_eq!(th.palette("flow_palette", 11), t["flow11"].as_str());
        assert_eq!(th.flag("effects", "shadow_enabled"), t["shadow_enabled"].as_bool());
        assert_eq!(th.string("shapes", "dash_pattern_dashed"), t["dash"].as_str());
    }
}
